import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiMail,
  FiCheckCircle,
  FiTrash2,
  FiEye,
  FiUser,
  FiClock,
  FiPhone,
  FiInbox,
} from 'react-icons/fi';

import api from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminCard from '../common/AdminCard';
import AdminModal from '../common/AdminModal';


// ==========================================
// ADMIN MESSAGES
// ==========================================
const AdminMessages = () => {

  // ========================================
  // STATES
  // ========================================
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);

  const [
    selectedMessage,
    setSelectedMessage,
  ] = useState(null);

  const [modalOpen, setModalOpen] =
    useState(false);


  // ========================================
  // LOAD MESSAGES
  // ========================================
  useEffect(() => {
    fetchMessages();
  }, []);


  // ========================================
  // FETCH MESSAGES
  // ========================================
  const fetchMessages = async () => {

    try {

      const response = await api.get(
        '/api/contact/'
      );

      setMessages(
        response.data || []
      );

    } catch (error) {

      console.error(
        'Fetch messages error:',
        error
      );

      toast.error(
        'Failed to load messages'
      );

    } finally {

      setLoading(false);

    }
  };


  // ========================================
  // MARK AS READ
  // ========================================
  const handleMarkRead = async (id) => {

    try {

      await api.put(
        `/api/contact/${id}/read`
      );

      toast.success(
        'Message marked as read'
      );

      fetchMessages();

    } catch (error) {

      console.error(
        'Mark read error:',
        error
      );

      toast.error(
        'Failed to mark message as read'
      );
    }
  };


  // ========================================
  // DELETE MESSAGE
  // ========================================
  const handleDelete = async (id) => {

    const confirmDelete =
      window.confirm(
        'Are you sure you want to delete this message?'
      );

    if (!confirmDelete) {
      return;
    }

    try {

      await api.delete(
        `/api/contact/${id}`
      );

      toast.success(
        'Message deleted successfully'
      );

      // Close modal if current message deleted
      if (
        selectedMessage &&
        selectedMessage.id === id
      ) {
        setModalOpen(false);
        setSelectedMessage(null);
      }

      fetchMessages();

    } catch (error) {

      console.error(
        'Delete message error:',
        error
      );

      toast.error(
        'Failed to delete message'
      );
    }
  };


  // ========================================
  // VIEW MESSAGE
  // ========================================
  const handleView = (message) => {

    setSelectedMessage(message);

    setModalOpen(true);

    if (!message.is_read) {
      handleMarkRead(message.id);
    }
  };


  // ========================================
  // CLOSE MODAL
  // ========================================
  const closeModal = () => {

    setModalOpen(false);

    setSelectedMessage(null);
  };


  // ========================================
  // UNREAD COUNT
  // ========================================
  const unreadCount = messages.filter(
    (message) => !message.is_read
  ).length;


  // ========================================
  // FORMAT DATE
  // ========================================
  const formatDate = (value) => {

    if (!value) {
      return '-';
    }

    const date = new Date(value);

    if (Number.isNaN(date.getTime())) {
      return '-';
    }

    return date.toLocaleString();
  };


  // ========================================
  // TABLE COLUMNS
  // ========================================
  const columns = [

    // ======================================
    // STATUS
    // ======================================
    {
      key: 'is_read',
      label: 'Status',

      render: (val) => (

        <span
          className={`
            inline-flex
            items-center
            gap-2

            px-3
            py-1.5

            rounded-full

            border

            text-xs
            font-semibold

            ${
              val
                ? `
                  bg-green-50
                  text-green-700
                  border-green-200
                `
                : `
                  bg-yellow-50
                  text-yellow-700
                  border-yellow-200
                `
            }
          `}
        >

          <span
            className={`
              w-2
              h-2

              rounded-full

              ${
                val
                  ? 'bg-green-500'
                  : 'bg-yellow-500'
              }
            `}
          />

          {val ? 'Read' : 'Unread'}

        </span>
      ),
    },


    // ======================================
    // NAME
    // ======================================
    {
      key: 'name',
      label: 'Name',

      render: (val) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-[#0B1A33]/5
              text-[#0B1A33]

              flex-shrink-0
            "
          >
            <FiUser size={17} />
          </div>

          <div>

            <p
              className="
                font-semibold
                text-[#0B1A33]
              "
            >
              {val || '-'}
            </p>

          </div>

        </div>
      ),
    },


    // ======================================
    // EMAIL
    // ======================================
    {
      key: 'email',
      label: 'Email',

      render: (val) => (

        <div
          className="
            flex
            items-center
            gap-2

            text-sm
            text-[#0B1A33]/60
          "
        >
          <FiMail
            size={15}
            className="
              text-[#0B1A33]/30
              flex-shrink-0
            "
          />

          <span>
            {val || '-'}
          </span>

        </div>
      ),
    },


    // ======================================
    // SUBJECT
    // ======================================
    {
      key: 'subject',
      label: 'Subject',

      render: (val) => (

        <span
          className="
            inline-block

            max-w-[220px]

            truncate

            text-sm
            font-medium

            text-[#0B1A33]
          "
        >
          {val || 'No subject'}
        </span>
      ),
    },


    // ======================================
    // DATE
    // ======================================
    {
      key: 'created_at',
      label: 'Date',

      render: (val) => (

        <div
          className="
            flex
            items-center
            gap-2

            text-sm
            text-[#0B1A33]/50

            whitespace-nowrap
          "
        >
          <FiClock
            size={14}
            className="text-[#0B1A33]/30"
          />

          {formatDate(val)}

        </div>
      ),
    },


    // ======================================
    // ACTIONS
    // ======================================
    {
      key: 'actions',
      label: 'Actions',

      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          {/* VIEW */}
          <button
            type="button"
            onClick={() =>
              handleView(row)
            }
            title="View Message"
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-[#0B1A33]/5
              text-[#0B1A33]

              hover:bg-[#0B1A33]
              hover:text-white

              transition-all
              duration-200
            "
          >
            <FiEye size={16} />
          </button>


          {/* MARK READ */}
          {!row.is_read && (

            <button
              type="button"
              onClick={() =>
                handleMarkRead(row.id)
              }
              title="Mark as Read"
              className="
                w-9
                h-9

                flex
                items-center
                justify-center

                rounded-lg

                bg-green-50
                text-green-600

                hover:bg-green-600
                hover:text-white

                transition-all
                duration-200
              "
            >
              <FiCheckCircle size={16} />
            </button>

          )}


          {/* DELETE */}
          <button
            type="button"
            onClick={() =>
              handleDelete(row.id)
            }
            title="Delete Message"
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-red-50
              text-red-600

              hover:bg-red-600
              hover:text-white

              transition-all
              duration-200
            "
          >
            <FiTrash2 size={16} />
          </button>

        </div>
      ),
    },
  ];


  // ========================================
  // RETURN
  // ========================================
  return (

    <div className="w-full">

      {/* ====================================
          PAGE HEADER
      ==================================== */}
      <div
        className="
          flex
          flex-col
          lg:flex-row

          lg:items-center
          lg:justify-between

          gap-4

          mb-7
        "
      >

        {/* LEFT */}
        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          {/* ICON */}
          <div
            className="
              w-12
              h-12

              flex
              items-center
              justify-center

              rounded-xl

              bg-[#0B1A33]
              text-white

              shadow-sm

              flex-shrink-0
            "
          >
            <FiMail size={22} />
          </div>


          {/* TITLE */}
          <div>

            <h1
              className="
                text-2xl
                md:text-3xl

                font-bold

                text-[#0B1A33]

                leading-tight
              "
            >
              Messages Management
            </h1>

            <p
              className="
                text-sm
                text-[#0B1A33]/50
                mt-1
              "
            >
              View and manage messages
              received from the contact form
            </p>

          </div>

        </div>


        {/* =================================
            COUNTERS
        ================================= */}
        <div
          className="
            flex
            flex-wrap
            items-center
            gap-3
          "
        >

          {/* UNREAD */}
          <div
            className="
              inline-flex
              items-center
              gap-2

              h-11

              px-4

              rounded-xl

              bg-yellow-50
              text-yellow-700

              border
              border-yellow-200

              text-sm
              font-semibold
            "
          >

            <span
              className="
                w-2.5
                h-2.5

                rounded-full

                bg-yellow-500
              "
            />

            {unreadCount} Unread

          </div>


          {/* TOTAL */}
          <div
            className="
              inline-flex
              items-center
              gap-2

              h-11

              px-4

              rounded-xl

              bg-[#0B1A33]/5
              text-[#0B1A33]

              border
              border-[#0B1A33]/10

              text-sm
              font-semibold
            "
          >
            <FiInbox size={17} />

            {messages.length} Total

          </div>

        </div>

      </div>


      {/* ====================================
          TABLE CARD
      ==================================== */}
      <AdminCard
        className="
          overflow-hidden

          bg-white

          border
          border-[#0B1A33]/10

          rounded-2xl

          shadow-sm
        "
      >

        <AdminTable
          columns={columns}
          data={messages}
          loading={loading}
        />

      </AdminCard>


      {/* ====================================
          MESSAGE DETAILS MODAL
      ==================================== */}
      <AdminModal
        isOpen={modalOpen}
        onClose={closeModal}
        title="Message Details"
      >

        {selectedMessage && (

          <div>

            {/* =================================
                SENDER HEADER - Navy Blue
            ================================= */}
            <div
              className="
                flex
                items-center
                gap-4

                p-4

                mb-5

                rounded-2xl

                bg-[#0B1A33]/5

                border
                border-[#0B1A33]/10
              "
            >

              {/* AVATAR ICON */}
              <div
                className="
                  w-12
                  h-12

                  flex
                  items-center
                  justify-center

                  rounded-xl

                  bg-[#0B1A33]
                  text-white

                  flex-shrink-0
                "
              >
                <FiUser size={21} />
              </div>


              <div className="min-w-0">

                <h3
                  className="
                    text-base
                    font-bold

                    text-[#0B1A33]

                    truncate
                  "
                >
                  {selectedMessage.name}
                </h3>

                <p
                  className="
                    text-sm
                    text-[#0B1A33]/50

                    truncate
                  "
                >
                  {selectedMessage.email}
                </p>

              </div>


              {/* STATUS */}
              <div className="ml-auto">

                <span
                  className="
                    inline-flex
                    items-center
                    gap-1.5

                    px-3
                    py-1.5

                    rounded-full

                    bg-green-50
                    text-green-700

                    border
                    border-green-200

                    text-xs
                    font-semibold
                  "
                >
                  <FiCheckCircle />

                  Read
                </span>

              </div>

            </div>


            {/* =================================
                INFO GRID
            ================================= */}
            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2

                gap-4
              "
            >

              {/* EMAIL */}
              <div
                className="
                  p-4

                  rounded-xl

                  border
                  border-[#0B1A33]/10

                  bg-[#0B1A33]/5
                "
              >

                <p
                  className="
                    text-xs
                    font-semibold

                    uppercase
                    tracking-wide

                    text-[#0B1A33]/30

                    mb-1.5
                  "
                >
                  Email
                </p>

                <div
                  className="
                    flex
                    items-center
                    gap-2

                    text-sm
                    font-medium

                    text-[#0B1A33]
                  "
                >
                  <FiMail
                    className="
                      text-[#0B1A33]
                      flex-shrink-0
                    "
                  />

                  <span
                    className="
                      break-all
                    "
                  >
                    {selectedMessage.email}
                  </span>

                </div>

              </div>


              {/* PHONE */}
              <div
                className="
                  p-4

                  rounded-xl

                  border
                  border-[#0B1A33]/10

                  bg-[#0B1A33]/5
                "
              >

                <p
                  className="
                    text-xs
                    font-semibold

                    uppercase
                    tracking-wide

                    text-[#0B1A33]/30

                    mb-1.5
                  "
                >
                  Phone
                </p>

                <div
                  className="
                    flex
                    items-center
                    gap-2

                    text-sm
                    font-medium

                    text-[#0B1A33]
                  "
                >
                  <FiPhone
                    className="
                      text-[#0B1A33]
                      flex-shrink-0
                    "
                  />

                  {selectedMessage.phone ||
                    'Not provided'}

                </div>

              </div>

            </div>


            {/* =================================
                SUBJECT
            ================================= */}
            <div className="mt-4">

              <p
                className="
                  text-sm
                  font-semibold

                  text-[#0B1A33]

                  mb-2
                "
              >
                Subject
              </p>

              <div
                className="
                  px-4
                  py-3

                  rounded-xl

                  bg-[#0B1A33]/5

                  border
                  border-[#0B1A33]/10

                  text-sm
                  font-medium

                  text-[#0B1A33]
                "
              >
                {selectedMessage.subject ||
                  'No subject'}
              </div>

            </div>


            {/* =================================
                MESSAGE
            ================================= */}
            <div className="mt-4">

              <p
                className="
                  text-sm
                  font-semibold

                  text-[#0B1A33]

                  mb-2
                "
              >
                Message
              </p>

              <div
                className="
                  min-h-[140px]

                  p-4

                  rounded-xl

                  bg-[#0B1A33]/5

                  border
                  border-[#0B1A33]/10

                  text-sm
                  text-[#0B1A33]

                  leading-7

                  whitespace-pre-wrap
                  break-words
                "
              >
                {selectedMessage.message}
              </div>

            </div>


            {/* =================================
                RECEIVED DATE
            ================================= */}
            <div
              className="
                mt-4

                flex
                items-center
                gap-2

                text-xs
                text-[#0B1A33]/30
              "
            >
              <FiClock />

              Received:

              <span className="font-medium text-[#0B1A33]/50">
                {formatDate(
                  selectedMessage.created_at
                )}
              </span>

            </div>


            {/* =================================
                FOOTER
            ================================= */}
            <div
              className="
                mt-7
                pt-5

                border-t
                border-[#0B1A33]/10

                flex
                flex-col-reverse
                sm:flex-row

                sm:items-center
                sm:justify-between

                gap-3
              "
            >

              {/* DELETE */}
              <button
                type="button"
                onClick={() =>
                  handleDelete(
                    selectedMessage.id
                  )
                }
                className="
                  h-11

                  inline-flex
                  items-center
                  justify-center
                  gap-2

                  px-5

                  rounded-xl

                  bg-red-50
                  text-red-600

                  border
                  border-red-100

                  text-sm
                  font-semibold

                  hover:bg-red-600
                  hover:text-white
                  hover:border-red-600

                  transition-all
                  duration-200
                "
              >
                <FiTrash2 size={16} />

                Delete Message
              </button>


              {/* CLOSE */}
              <button
                type="button"
                onClick={closeModal}
                className="
                  h-11

                  px-6

                  rounded-xl

                  bg-[#0B1A33]
                  hover:bg-[#0B1A33]/80

                  text-white

                  text-sm
                  font-semibold

                  shadow-sm
                  hover:shadow-md

                  transition-all
                  duration-200
                "
              >
                Close
              </button>

            </div>

          </div>

        )}

      </AdminModal>

    </div>
  );
};


export default AdminMessages;
